"""Draft eval scenarios from hand-written seeds plus the extracted fault records."""
from __future__ import annotations

import json
from pathlib import Path

import yaml

from faultsense.codes import code_key, confusable_variants

HEADER = (
    "# DRAFT eval scenarios generated by `faultsense eval draft` from data/eval/scenario_seeds.yaml and the fault\n"
    "# records in data/processed/. Every scenario is `reviewed: false` until a person has checked it.\n"
    "# Edit expectations while reviewing, then set `reviewed: true`.\n"
)


def load_faults(processed_dir: Path) -> dict[str, dict[str, dict]]:
    faults: dict[str, dict[str, dict]] = {}
    for path in sorted(Path(processed_dir).glob("*.json")):
        if path.name == "extraction_report.json":
            continue
        data = json.loads(path.read_text(encoding="utf-8"))
        faults[data["manual"]] = {record["code_key"]: record for record in data["faults"]}
    return faults


def _find(records: dict[str, dict], code: str) -> dict | None:
    key = code_key(code)
    if key in records:
        return records[key]
    for variant in sorted(confusable_variants(key)):
        if variant in records:
            return records[variant]
    return None


def _targets(seed: dict, faults: dict[str, dict[str, dict]]) -> list[tuple[str, dict]]:
    found = []
    for target in seed.get("targets", []):
        manuals = [target["manual"]] if "manual" in target else sorted(faults)
        for manual in manuals:
            record = _find(faults.get(manual, {}), target["code"])
            if record is not None:
                found.append((manual, record))
            elif "manual" in target:
                raise ValueError(f"{seed['id']}: code {target['code']} not found in {manual}")
    return found


def draft_scenarios(seeds: list[dict], faults: dict[str, dict[str, dict]]) -> list[dict]:
    drafted = []
    for seed in seeds:
        found = _targets(seed, faults)
        out_of_scope = seed["type"] == "out_of_scope"
        causes = seed.get("expected_causes") or (found[0][1]["causes"][:4] if found else [])
        sources = seed.get("expected_sources") or [
            {"manual": manual, "pages": list(range(record["page"], record["page_end"] + 1))}
            for manual, record in found
        ]
        if found:
            notes = "Drafted from " + ", ".join(f"{m} {r['code']} p.{r['page']}" for m, r in found)
        elif out_of_scope:
            notes = seed.get("notes", "Out of scope: the system must escalate")
        else:
            notes = seed.get("notes", "Expectations written by hand from the manual text")
        drafted.append({
            "id": seed["id"],
            "type": seed["type"],
            "query": seed["query"],
            "machine_id": seed.get("machine_id"),
            "expected_behavior": "escalate" if out_of_scope else "diagnose",
            "expected_fault_codes": list(dict.fromkeys(record["code"] for _, record in found)),
            "expected_causes": [] if out_of_scope else list(causes),
            "expected_sources": [] if out_of_scope else list(sources),
            "reviewed": False,
            "notes": notes,
        })
    return drafted


def write_scenarios(scenarios: list[dict], path: Path) -> Path:
    path.parent.mkdir(parents=True, exist_ok=True)
    body = yaml.safe_dump(scenarios, sort_keys=False, allow_unicode=True, width=110)
    path.write_text(HEADER + body, encoding="utf-8")
    return path
